-- Supabase DB-A local-only security/integrity assertions.
begin;
create extension if not exists pgtap with schema extensions;
select plan(31);
select has_schema('artales_evidence','private evidence schema created');
select has_table('artales_evidence','source_snapshots','raw snapshots exist');
select has_table('artales_evidence','source_components','source component map exists');
select has_table('artales_evidence','rights_dossiers','rights dossier exists');
select has_table('artales_evidence','rights_evidence','specific evidence exists');
select has_table('artales_evidence','text_revisions','semantic revisions exist');
select has_table('artales_evidence','metadata_revisions','metadata revisions exist');
select has_table('artales_evidence','visual_revisions','visual revisions exist');
select has_table('artales_evidence','review_events','review event history exists');
select is(has_schema_privilege('anon','artales_evidence','USAGE'),false,'anonymous users cannot access schema');
select is(has_schema_privilege('authenticated','artales_evidence','USAGE'),false,'signed clients cannot access internal schema');
select is(has_schema_privilege('anon','artales_evidence','CREATE'),false,'anon cannot create artifacts');
select is(has_schema_privilege('authenticated','artales_evidence','CREATE'),false,'clients cannot create artifacts');
select is(has_function_privilege('anon','artales_evidence.reject_mutation()','EXECUTE'),false,'immutable blocker not callable from anon');
select is(has_function_privilege('authenticated','artales_evidence.reject_mutation()','EXECUTE'),false,'immutable blocker not callable from authenticated');
select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='artales_evidence' and c.relkind='r' and c.relrowsecurity),8,'all 8 tables have RLS');
select is((select count(*)::integer from information_schema.role_table_grants where table_schema='artales_evidence' and grantee in ('authenticated','anon')),0,'no client table grants');
select is((select count(*)::integer from information_schema.role_table_grants where table_schema='artales_evidence' and grantee='PUBLIC'),0,'no PUBLIC table grants');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='artales_evidence' and p.prosecdef),0,'no SECURITY DEFINER functions');
select is((select count(*)::integer from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='artales_evidence' and not t.tgisinternal and t.tgname like 'immutable_%'),8,'eight mutation triggers installed');
select is((select count(*)::integer from artales_evidence.source_snapshots),0,'no legacy source snapshots seeded');
select is((select count(*)::integer from artales_evidence.review_events),0,'no forged reviews');
select is((select count(*)::integer from artales_evidence.rights_dossiers),0,'no assumed legal clearance');
select is((select count(*)::integer from artales_evidence.text_revisions),0,'no synthetic published revisions');
select is((select count(*)::integer from artales_evidence.visual_revisions),0,'no fake cleared assets');
select is((select count(*)::integer from artales_evidence.metadata_revisions),0,'no auto-approved metadata');
select is((select count(*)::integer from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='artales_evidence' and t.tgname in ('text_revision_hash','metadata_revision_hash','component_source_range','evidence_source_match')),4,'four insert validators installed');
select is(has_function_privilege('anon','artales_evidence.hash_revision_on_insert()','EXECUTE'),false,'anon cannot call hash trigger');
select is(has_function_privilege('authenticated','artales_evidence.validate_component_span()','EXECUTE'),false,'signed clients cannot call span validator');
select is((select count(*)::integer from pg_constraint where conname in ('rights_dossier_snapshot_same_work','text_revision_snapshot_same_work','text_revision_parent_same_work','metadata_revision_parent_same_work')),4,'same-work composite FKs exist');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='artales_evidence' and p.prosecdef),0,'new validator functions remain invoker-only');
select * from finish();
rollback;
